// Jedno zgłoszenie (formularz n8n, landing tekst/głos, Fireflies, Gmail) -> wspólny format dla reszty workflow.
// Bierzemy WSZYSTKIE źródła treści naraz (transkrypcja nagrania, tekst, persona, wiadomość), a nie tylko pierwsze znalezione.
const j = $json;
const b = j.body && typeof j.body === 'object' ? j.body : j; // webhook trzyma dane w body
const str = (v) => (v == null ? '' : typeof v === 'object' ? String(v.text ?? v.value ?? '') : String(v)).trim();
const pick = (...vals) => vals.map(str).find(Boolean) || '';
const get = (k) => b[k] ?? j[k];

let source = 'inne';
try {
  source = { Form: 'formularz n8n', 'Website form': 'formularz WWW', 'Nagranie do przepisania?': 'formularz WWW', 'Dołącz transkrypcję': 'formularz WWW (nagranie przepisane w n8n)', 'Transkrypcja z fireflies': 'Fireflies', 'Potwierdź odbiór (Fireflies)': 'Fireflies', 'Gmail Trigger': 'Gmail' }[$prevNode.name] || $prevNode.name;
} catch {}
if (b.source) source = `${source} (${b.source}${b.mode ? `, ${b.mode}` : ''})`;

// --- treść: każda część osobno, z etykietą ---
const parts = [];
const add = (label, v) => {
  const t = str(v);
  if (t && !parts.some((p) => p.text === t)) parts.push({ label, text: t });
};

// Fireflies: podsumowanie i wypowiedzi
const ff = b.data?.transcript || b.transcript || {};
add('Podsumowanie spotkania (Fireflies)', b.summary?.overview || ff.summary?.overview);
const sentences = b.sentences || ff.sentences;
if (Array.isArray(sentences)) add('Transkrypcja spotkania', sentences.map((s) => `${s.speaker_name || s.speaker || ''}: ${s.text || s.raw_text || ''}`).join('\n'));

// Landing: nagranie głosowe, tekst klienta, przykładowa persona
const voice = b.voice || {};
add(`Transkrypcja nagrania głosowego${voice.seconds ? ` (${voice.seconds} s)` : ''}`, voice.transcript || voice.sampleTranscript);
add('Tekst od klienta', b.brief?.text);
add('Opis potrzeb', pick(get('Opis potrzeb'), get('message'), get('wiadomosc'), get('wiadomość'), get('opis'), get('notes'), get('description')));
if (typeof b.transcript === 'string') add('Transkrypcja', b.transcript);
add('Treść', pick(get('text'), get('textPlain'), get('snippet')));
// landing wysyła tekst persony jako sampleText (starsze wersje: text)
const personaText = b.tryItAs && (b.tryItAs.text || b.tryItAs.sampleText);
if (personaText) add(`Przykładowa persona wybrana na stronie: ${b.tryItAs.label || b.tryItAs.persona || ''}`, personaText);
// rola kliknięta na stronie ("Pick your role"): model dostaje ją słowami, także gdy nie ma dla niej kafelka
const PICKED = { champion: 'Team champion (prawnik, który chce wdrożyć narzędzie w zespole)', board: 'Board or managing partner (zarząd, decyduje o budżecie)', legal: 'Head of Legal (szef działu prawnego)', budget: 'Budget owner (właściciel budżetu, pyta o zwrot z inwestycji)', it: 'IT or CTO (dział IT, pyta o infrastrukturę i bezpieczeństwo)', dpo: 'DPO or compliance (ochrona danych osobowych)' };
if (b.pickedRole) add('Rola wybrana na stronie', PICKED[b.pickedRole] || String(b.pickedRole));

const subject = pick(get('Subject'), get('subject'));
if (subject && /Gmail/.test(source)) parts.unshift({ label: 'Temat e-maila', text: subject });

const text = parts.map((p) => `## ${p.label}\n${p.text}`).join('\n\n').slice(0, 20000);

// --- kontakt ---
let email = pick(get('E-mail'), get('email'), get('mail'), get('From'), get('from'));
const m = email.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
email = m ? m[0] : email;

// --- podpowiedzi -> id kafelków (wybór klienta ma pierwszeństwo przed personą demo) ---
const low = (s) => str(s).toLowerCase();
const asTile = (prefix, v) => (v ? (v.startsWith(`${prefix}:`) ? v : `${prefix}:${v}`) : null);
const segRaw = low(pick(b.brief?.segment, get('Segment'), get('segment'), b.tryItAs?.segment));
const roleRaw = low(pick(b.brief?.role, b.pickedRole, get('Twoja rola'), get('Rola'), get('role'), b.tryItAs?.role));
const prodRaw = low(pick(get('Produkt'), get('product'), get('produkt')));
const hints = {
  segment: /^(segment:)?(law-firm|in-house|public-sector|finance|tax-advisors|notaries|mass-claims)$/.test(segRaw) ? asTile('segment', segRaw)
    : /kancel|law/.test(segRaw) ? 'segment:law-firm' : /dział|dzial|in-house|firm/.test(segRaw) ? 'segment:in-house' : /publi|urząd|urzad/.test(segRaw) ? 'segment:public-sector' : null,
  role: /^(role:)?(board|champion|cto|gc|budget|dpo)$/.test(roleRaw) ? asTile('role', roleRaw)
    : /zarz|partner|board|dyrek|prezes|ceo/.test(roleRaw) ? 'role:board' : /prawnik|lider|champion|radca|adwokat/.test(roleRaw) ? 'role:champion' : null,
  product: /^(product:)?(saas|vault|on-prem)$/.test(prodRaw) ? asTile('product', prodRaw)
    : /on-?prem|serwer/.test(prodRaw) ? 'product:on-prem' : /saas|chmur/.test(prodRaw) ? 'product:saas' : /vault/.test(prodRaw) ? 'product:vault' : null,
};
for (const k of Object.keys(hints)) if (!hints[k]) delete hints[k];

return {
  json: {
    source,
    company: pick(get('Firma'), get('company'), get('firma'), get('organization'), get('organizacja'), get('client'), get('klient')),
    contact_name: pick(get('Imię i nazwisko'), get('name'), get('imie'), get('contact'), get('kontakt')) || pick(get('From'), get('from')).replace(/<.*>/, '').trim(),
    email,
    hints,
    price: pick(get('Cena'), get('price'), get('cena')),
    language: str(b.language),
    parts: parts.map((p) => p.label),
    text,
    received_at: new Date().toISOString(),
  },
};

// Odpowiedź AI -> sprawdzone kafelki (1 rola, 1 segment, 1 produkt, 1–5 problemów).
// Gdy odpowiedź jest zła, a to pierwsza próba, odsyłamy AI opis błędu (retry: true) i AI poprawia się samo.
const MAX_TRIES = 2; // one correction at most: the second answer is used as it is (valid parts kept)
const attempt = $runIndex + 1;
const lead = $('Normalizuj zgłoszenie').first().json;
const tiles = $('Kontekst dla AI').first().json.tiles;
const raw = String($json.output ?? $json.text ?? '');

// Tolerancyjny parser: wycina JSON z tekstu i naprawia typowe błędy modeli.
function parseLoose(text) {
  let s = text.replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('w odpowiedzi nie ma obiektu JSON');
  s = s.slice(a, b + 1);
  const tries = [
    (x) => x,
    (x) => x.replace(/„([^"„”\n]*)"/g, '„$1”'), // „cytat" -> „cytat”
    (x) => x.replace(/[“”]/g, '\\"').replace(/„/g, '\\"'), // typograficzne cudzysłowy
    (x) => x.replace(/,\s*([}\]])/g, '$1'), // przecinek przed } lub ]
  ];
  let cur = s;
  let lastErr;
  for (const fix of tries) {
    cur = fix(cur);
    try { return JSON.parse(cur); } catch (e) { lastErr = e; }
  }
  throw new Error(`niepoprawny JSON (${lastErr.message})`);
}

const problems = [];
let ai = {};
try {
  ai = parseLoose(raw);
} catch (e) {
  problems.push(e.message);
}

const ids = new Set(tiles.map((t) => t.id));
const cat = (id) => tiles.find((t) => t.id === id)?.category;
const okIn = (id, category) => id && ids.has(id) && cat(id) === category;

if (!problems.length) {
  for (const k of ['role', 'segment', 'product']) {
    if (ai[k] && !okIn(ai[k], k)) problems.push(`"${k}": "${ai[k]}" nie jest kafelkiem kategorii ${k} z listy`);
  }
  const badPains = (Array.isArray(ai.pains) ? ai.pains : []).filter((id) => !okIn(id, 'pain'));
  if (badPains.length) problems.push(`"pains" zawiera nieistniejące kafelki: ${badPains.join(', ')}`);
  if (!(Array.isArray(ai.pains) && ai.pains.some((id) => okIn(id, 'pain')))) problems.push('"pains" musi mieć 1–5 kafelków pain:… z listy');
}

if (problems.length && attempt < MAX_TRIES) {
  return [{ json: { retry: true, attempt, problems, raw: raw.slice(0, 4000) } }];
}
// Nic użytecznego po 2 próbach (np. „Chcę AI.”): nie przerywamy, oferta powstaje z bezpiecznych domyślnych kafelków.
if (!ai || typeof ai !== 'object') ai = {};

// Ostatnia próba albo wszystko OK: bierzemy to, co poprawne, resztę uzupełniamy bezpiecznymi domyślnymi.
const one = (category, ...candidates) => candidates.find((id) => okIn(id, category))
  || tiles.find((t) => t.category === category)?.id;
const role = one('role', lead.hints.role, ai.role, 'role:champion');
const segment = one('segment', lead.hints.segment, ai.segment);
// Produkt idzie za rozmówcą, nie za firmą: Board -> Vault, Champion -> SaaS (sam testuje, 14-dniowy trial).
// On-prem tylko, gdy rozmówca wymaga własnej infrastruktury (AI to rozpoznało) albo produkt przyszedł z formularza.
const byPerson = role === 'role:board' ? 'product:vault' : 'product:saas';
// Własny serwer powiedziany wprost = on-prem zawsze, bez zgadywania modelu.
// \p{L} with the u flag: \w does not match Polish letters, so „naszą infrastrukturę” used to slip through
const ownServer = /(na|u nas na|nasz\p{L}*|własn\p{L}*|swoi\p{L}*|swoim)\s+serwer|serwer\p{L}*\s+(u nas|w firmie|w kancelarii|w urzędzie)|on-?prem|(lokaln|nasz|własn)\p{L}* infrastruktur|opu[sś]ci[ćc] (nasz|nasze|naszej|naszych) |nie mo[gż]\p{L}* wyj[sś][ćc] poza (nasz|firm|kancelari|urz)|own server|on our servers?|on-?premise|own infrastructure/iu.test(lead.text || '');
const product = one('product', lead.hints.product, ownServer || ai.product === 'product:on-prem' ? 'product:on-prem' : null, byPerson, 'product:vault');
let pains = [...new Set((Array.isArray(ai.pains) ? ai.pains : []).map(String))].filter((id) => okIn(id, 'pain')).slice(0, 5);
if (!pains.length) pains = [tiles.find((t) => t.category === 'pain').id];

// bez nazwy firmy: opis zamiast nazwy, bo szablon wstawia ją w nagłówki ("Proposal for …", "Rollout plan for …")
const GENERIC = { 'segment:law-firm': 'your law firm', 'segment:in-house': 'your legal team', 'segment:public-sector': 'your office' };
// Nazwa od AI tylko wtedy, gdy to nazwa własna, która padła w zgłoszeniu. Model potrafi zwrócić opis
// („Kancelaria (Warszawa i Poznań) – nazwa niepodana”, „Piekarnia rzemieślnicza w Krakowie”), a ten trafiłby na tytuł decku.
const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const aiName = String(ai.client && ai.client !== 'null' ? ai.client : '').trim();
const GENERIC_START = /^(kancelari|dział|dzial|urząd|urzad|firm|spółk|spolk|ministerstw|departament|bank|grup|piekarni|zespół|zespol|biur|wydział|wydzial|organizacj|instytucj|law firm|legal|company|office|team|the |a |an |your )/i;
// After a generic first word ("Kancelaria", "Grupa", "Departament") a name needs a proper noun of its own:
// "Kancelaria Wrona Lis" and "Grupa Budimex" are names, "Departament Prawny ministerstwa" is a description.
const GENERIC_WORD = /^(prawn|praw|legal|ministerstw|urzęd|urzed|miejsk|gmin|grup|kapitałow|kapitalow|spółk|spolk|zespoł|zespol|dział|dzial|kancelari|biur|firm|bank|department|departament|office|team|group|company)/i;
const capitals = aiName.split(/\s+/).slice(1).filter((t) => /^[A-ZĄĆĘŁŃÓŚŹŻ]/.test(t) && !GENERIC_WORD.test(t)).length;
const aiNameOk = aiName.length >= 2 && aiName.length <= 80
  && norm(lead.text).includes(norm(aiName))
  && !/nazw|niepodan|unknown|brak|null|[()]/i.test(aiName)
  && (capitals >= 1 || !GENERIC_START.test(aiName));
const named = String(lead.company || (aiNameOk ? aiName : '') || '').trim();
const client = named || GENERIC[segment] || 'your team';
return [{
  json: {
    retry: false,
    attempt,
    warnings: problems,
    // made_by: Offer Studio keeps the model's tiles and the enquiry, so the team's later changes show up as corrections
    // to teach from (Lessons); lessons: which lessons the model was given
    request: {
      client, tiles: [role, segment, product, ...pains], ...(lead.price ? { price: lead.price } : {}),
      made_by: 'n8n (AI)', enquiry: String(lead.text || '').slice(0, 8000), summary: String(ai.summary || ''),
      lessons: $('Kontekst dla AI').first().json.lessons || [],
    },
    client,
    analysis: ai.analysis || null,
    summary: String(ai.summary || ''),
    reasons: ai.reasons || {},
  },
}];

// Kafelki z Offer Studio -> prompt dla AI. AI wybiera kafelki, a ofertę buduje Studio (POST /api/offers/generate).
const lead = $('Normalizuj zgłoszenie').first().json;
const tiles = ($('Kafelki').first().json.data || []).filter((t) => t.status !== 'soon');
// Lekcje od zespołu sprzedaży (Offer Studio ▸ Lessons): poprawki do wcześniejszych wyborów modelu.
const lessons = Array.isArray($json.data) ? $json.data : [];
const oneLine = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const lessonLines = lessons.map((l) => {
  const ex = l.example || {};
  const example = ex.before || ex.after
    ? `\n    przykład: model wybrał «${oneLine(ex.before) || '-'}», zespół poprawił na «${oneLine(ex.after) || '-'}»${ex.quote ? `; zgłoszenie: «${oneLine(ex.quote).slice(0, 300)}»` : ''}`
    : '';
  return `- ${oneLine(l.text)}${(l.tiles || []).length ? ` (dotyczy: ${l.tiles.join(', ')})` : ''}${example}`;
}).join('\n');
const byCat = (cat) => tiles.filter((t) => t.category === cat)
  // opis kafelka + kiedy go wybrać i kiedy nie (te same wskazówki widzi handlowiec w Offer Studio)
  .map((t) => {
    const one = (s) => String(s || '').replace(/\s+/g, ' ').trim();
    const pick = one(t.data && t.data.pick_when);
    const avoid = one(t.data && t.data.avoid_when);
    return `- ${t.id} | ${t.label} | ${one(t.description)}${pick ? `\n    wybierz, gdy: ${pick}` : ''}${avoid ? `\n    nie wybieraj, gdy: ${avoid}` : ''}`;
  }).join('\n');

const prompt = `# Zgłoszenie (${lead.source})
Firma: ${lead.company || '(nie podano)'}
Kontakt: ${lead.contact_name || '-'} ${lead.email ? `<${lead.email}>` : ''}
Podpowiedzi z formularza: ${JSON.stringify(lead.hints)}
Treść (${(lead.parts || []).length} części):
"""
${lead.text || '(brak treści)'}
"""

# Kafelki: rola (dokładnie 1)
${byCat('role')}

# Kafelki: segment (dokładnie 1)
${byCat('segment')}

# Kafelki: produkt (dokładnie 1)
${byCat('product')}

# Kafelki: problemy (1–5, najważniejsze najpierw)
${byCat('pain')}
${lessons.length ? `\n# Lekcje od zespołu sprzedaży\nPoprawki handlowców do wcześniejszych wyborów. Stosuj lekcję, gdy pasuje do tego zgłoszenia; ma pierwszeństwo przed ogólnymi wskazówkami.\n${lessonLines}\n` : ''}
Odpowiedz wyłącznie obiektem JSON według schematu z instrukcji systemowej.`;

return [{ json: { prompt, tiles: tiles.map((t) => ({ id: t.id, category: t.category })), lessons: lessons.map((l) => l.id) } }];

// Krótkie podsumowanie dla zespołu (Discord) + PDF w binarnym polu "data".
const plan = $('Przygotowanie scenariusza').first().json;
const lead = $('Normalizuj zgłoszenie').first().json;
const check = $('Sprawdź treść').last().json;
const offer = $('Zapisz treść').first().json;
const STUDIO_URL = 'https://studio.bizhack.trygaius.com';
const link = `${STUDIO_URL}/#/offers/${encodeURIComponent(offer.id)}`;

const slides = offer.slides || [];
const written = slides.filter((s) => s.origin && s.origin.written_by).map((s) => s.origin.label || s.frame);
const comparison = slides.find((s) => s.frame === 'tool-comparison');

// Nagranie przepisywane w n8n (ElevenLabs): przy błędzie (np. brak lub zły klucz) zespół widzi to od razu,
// zamiast cichej oferty z domyślnych kafelków.
let voiceNote = '';
try {
  if ($('Dołącz transkrypcję').isExecuted) {
    const v = (($('Dołącz transkrypcję').first().json.body) || {}).voice || {};
    voiceNote = v.transcribedBy
      ? `🎙️ Nagranie przepisane w n8n (${v.transcribedBy})`
      : `⚠️ Nagranie NIE zostało przepisane (${String(v.transcriptionError || 'brak tekstu').slice(0, 160)}), oferta z domyślnych kafelków. Sprawdź ELEVENLABS_API_KEY i zrestartuj n8n.`;
  }
} catch {}

const message = [
  `📄 Nowa oferta: **${offer.name || plan.client}**`,
  `Źródło: ${lead.source}${lead.contact_name ? ` · ${lead.contact_name}` : ''}${lead.email ? ` <${lead.email}>` : ''}`,
  `Kafelki: ${plan.request.tiles.join(', ')}`,
  voiceNote,
  `Treść od AI: ${written.length ? written.join(', ') : 'brak (teksty domyślne)'}${comparison ? ` · porównanie z narzędziem: ${comparison.hidden ? 'ukryte' : 'pokazane'}` : ''}`,
  check.warnings && check.warnings.length ? `⚠️ Pominięte przy zapisie (zostały teksty domyślne): ${check.warnings.slice(0, 5).join('; ')}` : '',
  plan.summary ? `\n${plan.summary}` : '',
  `\nEdycja w Offer Studio: ${link}`,
].filter(Boolean).join('\n');

return [{
  json: { offer_id: offer.id, offer_name: offer.name, offer_url: link, pdf_url: `${STUDIO_URL}/api/offers/${encodeURIComponent(offer.id)}/pdf`, tiles: plan.request.tiles, written, warnings: check.warnings || [], message },
  binary: $input.first().binary,
}];

// Samopoprawka: ten sam prompt + lista błędów z poprzedniej odpowiedzi. Wraca do AI Agent.
const base = $('Kontekst dla AI').first().json.prompt;
return [{
  json: {
    prompt: `${base}

# Poprawka (próba ${$json.attempt + 1})
Twoja poprzednia odpowiedź nie przeszła walidacji:
${$json.problems.map((p) => `- ${p}`).join('\n')}

Poprzednia odpowiedź:
"""
${$json.raw}
"""

Zwróć cały obiekt JSON jeszcze raz, poprawiony. Używaj wyłącznie id kafelków z listy. W tekstach nie używaj znaku " (cytaty pisz w « »).`,
  },
}];

// Pola slajdów z Offer Studio (GET /api/offers/:id/content) + zgłoszenie -> prompt dla AI, które pisze treść oferty.
// Opisy pól (co napisać, limit znaków, liczba kart) są w scenariuszu w Offer Studio (zakładka Scenarios), nie tutaj.
const lead = $('Normalizuj zgłoszenie').first().json;
const plan = $('Przygotowanie scenariusza').first().json;
const ctx = $json;

const describe = (f) => f.kind === 'text'
  ? `tekst, maks. ${f.max} znaków. ${f.hint}\n    domyślnie: ${JSON.stringify(f.current)}`
  : `lista ${f.min}–${f.max} pozycji. ${f.hint}\n    kolumny: ${Object.entries(f.columns).map(([k, c]) => `${k} (maks. ${c.max} znaków): ${c.hint}`).join('; ')}\n    domyślnie: ${JSON.stringify(f.current)}`;
// Biblioteka Offer Studio: co wiemy o bólach klienta i jak je rozwiązujemy (fakty o produkcie).
const ev = ctx.evidence || { pains: [] };
const evidence = ev.pains.map((p) => [
  `## ${p.label}${p.description ? `: ${p.description}` : ''}`,
  p.typical_quotes?.length ? `Typowe cytaty innych klientów (NIE tego klienta): ${p.typical_quotes.map((q) => `‘${q}’`).join('; ')}` : '',
  p.no_solution ? 'Rozwiązanie: brak w bibliotece. Nie obiecuj rozwiązania tego bólu.' : '',
  ...p.solutions.map((s) => `- rozwiązanie${s.general ? ' (ogólne, z innego segmentu: dopasuj do tego klienta, bez szczegółów branżowych)' : ''}: ${s.title}. ${s.text}${s.effect ? ` Efekt: ${s.effect}` : ''}${s.value ? ` Wartość: ${s.value}` : ''}`),
  ...p.proof.map((s) => `- dowód (${s.type}): ${s.title}. ${s.text}`),
].filter(Boolean).join('\n')).join('\n\n');

// Obiekcje, które zgłaszają klienci, z naszą odpowiedzią dla tego produktu i segmentu (z arkusza sprzedaży).
const objections = (ev.objections || []).map((o) => [
  `- ${o.concern}${o.typical_quotes?.length ? ` (słowa innych klientów: ${o.typical_quotes.map((q) => `‘${q}’`).join('; ')})` : ''}`,
  `  Nasza odpowiedź: ${o.answer}${o.no_answer ? ' [brak pełnej potwierdzonej odpowiedzi: nie obiecuj nic ponad to zdanie]' : ''}`,
  o.note ? `  Uwaga: ${o.note}` : '',
].filter(Boolean).join('\n')).join('\n');

// Fakty o innych narzędziach (Copilot, ChatGPT, LEX/Legalis) z arkusza sprzedaży: jedyne źródło kolumny narzędzia w porównaniu.
const tools = (ev.tools || []).map((t) => [
  `## ${t.name} (rozpoznawane jako: ${t.aliases.join(', ')})`,
  ...t.facts.map((x) => `- ${x.area} | narzędzie: ‘${x.them}’ | my: ‘${x.us}’${x.their_strength ? ' [przewaga narzędzia: tylko gdy klient sam o tym mówił]' : ''}`),
].join('\n')).join('\n\n');

const slides = ctx.slides.map((s) => [
  `## ${s.step} (${s.label})${s.optional ? ' [OPCJONALNY: napisz go tylko, gdy ma podstawę w zgłoszeniu; inaczej {"hide": true}]' : ''}`,
  ...Object.entries(s.fields).map(([k, f]) => `- ${k}: ${describe(f)}`),
].join('\n')).join('\n\n');

// Lekcje od zespołu sprzedaży (Offer Studio ▸ Lessons), tylko te, które pasują do kafelków tej oferty.
const lessons = (ctx.lessons || []).map((l) => {
  const ex = l.example || {};
  const cut = (s) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, 400);
  return `- ${l.step ? `[slajd ${l.step}] ` : ''}${cut(l.text)}${ex.before || ex.after ? `\n  przykład poprawki${ex.field ? ` (${ex.field})` : ''}: model napisał «${cut(ex.before)}», zespół poprawił na «${cut(ex.after)}»` : ''}`;
}).join('\n');

const prompt = `# Klient
Firma: ${ctx.client}
Produkt w ofercie: ${ctx.product_name}${ctx.product && ctx.product.brief ? `\nCo podkreślać w tym produkcie: ${ctx.product.brief}` : ''}
Kafelki: ${(ctx.client_tiles || []).map((t) => `${t.label || t.id}`).join(', ')}
Notatka handlowca (z analizy zgłoszenia): ${plan.summary || '-'}

# Odbiorca prezentacji: ${ctx.reader ? ctx.reader.label : 'nieznany'}
${ctx.reader ? [ctx.reader.description, ctx.reader.brief].filter(Boolean).join('\n') : 'Pisz neutralnie.'}

# Zgłoszenie (${lead.source})
"""
${lead.text || '(brak treści)'}
"""

# Biblioteka: bóle klienta i nasze rozwiązania (segment: ${ev.segment ? ev.segment.label : '-'}, produkt: ${ev.product ? ev.product.label : '-'})
${evidence || '(brak)'}

# Biblioteka: obiekcje klientów i nasze odpowiedzi
To ściąga, nie lista do wypełnienia: użyj tylko obiekcji, które TEN klient sam zgłosił w zgłoszeniu (choćby innymi słowami). Resztę pomiń.
${objections || '(brak)'}

# Biblioteka: fakty o innych narzędziach (do slajdu tool-comparison)
${tools || '(brak)'}

# Slajdy i pola do napisania
${slides}
${lessons ? `\n# Lekcje od zespołu sprzedaży\nPoprawki handlowców do wcześniejszych ofert. Stosuj je: mają pierwszeństwo przed ogólnymi wskazówkami, ale nie pozwalają wymyślać faktów.\n${lessons}\n` : ''}
Odpowiedz wyłącznie obiektem JSON według schematu z instrukcji systemowej.`;

return [{ json: { prompt, offer_id: ctx.offer_id, context: ctx } }];

// Odpowiedź AI -> treść slajdów sprawdzona według pól z Offer Studio (te same reguły co PUT /api/offers/:id/content).
// Zła odpowiedź, a to pierwsza próba: odsyłamy AI listę błędów (retry: true).
// Ostatnia próba: zostawiamy to, co poprawne (pole za długie albo z złą liczbą pozycji zostaje domyślne).
const MAX_TRIES = 2; // one correction at most: the second answer is used as it is (valid parts kept)
const attempt = $runIndex + 1;
const ctx = $('Kontekst treści').first().json.context;
const raw = String($json.output ?? $json.text ?? '');

function parseLoose(text) {
  let s = text.replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('w odpowiedzi nie ma obiektu JSON');
  s = s.slice(a, b + 1);
  const tries = [
    (x) => x,
    (x) => x.replace(/„([^"„”\n]*)"/g, '„$1”'),
    (x) => x.replace(/[“”]/g, '\\"').replace(/„/g, '\\"'),
    (x) => x.replace(/,\s*([}\]])/g, '$1'),
  ];
  let cur = s;
  let lastErr;
  for (const fix of tries) {
    cur = fix(cur);
    try { return JSON.parse(cur); } catch (e) { lastErr = e; }
  }
  throw new Error(`niepoprawny JSON (${lastErr.message})`);
}

const problems = [];
let ai = {};
try { ai = parseLoose(raw); } catch (e) { problems.push(e.message); }

// Obawy klienta (team-support.concerns) muszą pochodzić ze zgłoszenia: model podaje przy każdej pole "said" ze słowami
// klienta, a my sprawdzamy, że te słowa są w treści zgłoszenia. Obawa bez pokrycia wypada; gdy nie zostanie żadna,
// pole zostaje domyślne. "said" nie trafia na slajd (kolumny slajdu to tylko title i value).
{
  const leadAll = String($('Normalizuj zgłoszenie').first().json.text || '').toLowerCase();
  const stems = (s) => String(s || '').toLowerCase().split(/[^a-ząćęłńóśźż0-9]+/i).filter((x) => x.length >= 4).map((x) => x.slice(0, 5));
  const leadStems = new Set(stems(leadAll));
  const saidInLead = (said) => { const s = stems(said); return s.length > 0 && s.filter((x) => leadStems.has(x)).length / s.length >= 0.6; };
  const ts = ai && ai.slides && ai.slides['team-support'];
  if (ts && Array.isArray(ts.concerns)) {
    const kept = ts.concerns.filter((c) => c && saidInLead(c.said));
    // "said" stays in the answer (a correction round shows it to the model again); the slide takes only its columns.
    if (kept.length) ts.concerns = kept; else delete ts.concerns;
  }
}

const clean = (v) => String(v ?? '').replace(/\s*\|\s*/g, ' / ').replace(/\s*\n\s*/g, ' ').trim();
// Ostatnia próba: tekst za długi skracamy do ostatniego pełnego zdania (albo członu przed średnikiem), które się
// mieści w limicie, zamiast tracić całe pole. Bez takiego miejsca pole zostaje domyślne, jak dotąd.
const lastTry = attempt >= MAX_TRIES;
const fit = (v, max) => {
  const ends = [...v.slice(0, max + 1).matchAll(/[.;!?](?=\s|$)/g)].map((m) => m.index).filter((i) => i < max && i >= Math.min(40, max * 0.4));
  if (!ends.length) return null;
  const at = ends[ends.length - 1];
  return v.slice(0, at).trim() + (v[at] === ';' ? '.' : v[at]);
};
const byStep = Object.fromEntries(ctx.slides.map((s) => [s.step, s]));
const out = {};
for (const [step, fields] of Object.entries((ai && ai.slides) || {})) {
  const slot = byStep[step];
  if (!slot) { problems.push(`"${step}": nie ma takiego slajdu (są: ${Object.keys(byStep).join(', ')})`); continue; }
  if (!fields || typeof fields !== 'object') { problems.push(`"${step}": oczekiwany obiekt pól`); continue; }
  const ok = {};
  for (const [key, value] of Object.entries(fields)) {
    const at = `${step}.${key}`;
    if (key === 'hide') {
      if (slot.optional) ok.hide = !!value; else problems.push(`"${at}": ukryć można tylko slajd opcjonalny`);
      continue;
    }
    const f = slot.fields[key];
    if (!f) { problems.push(`"${at}": tego pola się nie pisze (pola: ${Object.keys(slot.fields).join(', ')})`); continue; }
    if (f.kind === 'text') {
      const v = typeof value === 'string' ? value.trim() : '';
      if (!v) { problems.push(`"${at}": oczekiwany niepusty tekst`); continue; }
      if (v.length > f.max) {
        const short = lastTry && fit(v, f.max);
        if (short) { ok[key] = short; continue; }
        problems.push(`"${at}": ${v.length} znaków, maks. ${f.max}`); continue;
      }
      ok[key] = v;
      continue;
    }
    if (!Array.isArray(value)) { problems.push(`"${at}": oczekiwana lista ${f.min}–${f.max} pozycji`); continue; }
    if (value.length < f.min || value.length > f.max) { problems.push(`"${at}": ${value.length} pozycji, oczekiwane ${f.min}–${f.max}`); continue; }
    const items = [];
    let bad = false;
    value.forEach((item, i) => {
      const row = {};
      for (const [k, col] of Object.entries(f.columns)) {
        const v = clean(item && item[k]);
        if (k === 'title' && !v) { problems.push(`"${at}[${i}].title": pusty`); bad = true; }
        if (col.max && v.length > col.max) {
          const short = lastTry && fit(v, col.max);
          if (short) { row[k] = short; continue; }
          problems.push(`"${at}[${i}].${k}": ${v.length} znaków, maks. ${col.max}`); bad = true;
        }
        row[k] = v;
      }
      items.push(row);
    });
    if (!bad) ok[key] = items;
  }
  if (Object.keys(ok).length) out[step] = ok;
}

// Porównanie tylko z narzędziem, które klient naprawdę wymienił: inaczej slajd zostaje ukryty.
// Bez nazwy narzędzia od modelu bierzemy ją z wypowiedzi klienta.
const leadRaw = String($('Normalizuj zgłoszenie').first().json.text || '');
const leadText = leadRaw.toLowerCase();
// polska odmiana też się liczy: Copilota, ChatGPT-a, Gemini, Lexa, Legalisa
const KNOWN = [['ChatGPT', /\bchat ?gpt/i], ['Copilot', /\bcopilot/i], ['Gemini', /\bgemini/i], ['Claude', /\bclaude/i], ['Perplexity', /\bperplexit/i], ['Harvey', /\bharvey/i], ['Lex', /\blex(a|ie|em|u)?\b/i], ['Legalis', /\blegalis/i], ['DeepSeek', /\bdeep ?seek/i], ['Le Chat', /\ble chat\b/i]];
const mentioned = KNOWN.filter(([, re]) => re.test(leadRaw)).map(([name]) => name);
const cmp = out['tool-comparison'];
if (cmp && !cmp.hide) {
  const tool = String(cmp.tool || (ai && ai.slides && ai.slides['tool-comparison'] && ai.slides['tool-comparison'].tool) || '');
  const words = tool.toLowerCase().split(/[^a-ząćęłńóśźż0-9]+/i).filter((x) => x.length >= 3 && !['general','chatbots','chatbot','tools','tool','free','public','other'].includes(x));
  const named = words.some((x) => leadText.includes(x));
  if (!named && !mentioned.length) out['tool-comparison'] = { hide: true };
  else if (!named) cmp.tool = mentioned.join(' / ');
}

// Reguły stylu sprawdzane automatycznie (model czasem je pomija): pole, które je łamie, idzie do poprawki.
const tileLabels = new Set((ctx.client_tiles || []).map((t) => String(t.label || '').toLowerCase()).filter(Boolean));
const STYLE = [
  [/\b(she|he|her|his)\b/i, 'pisz do odbiorcy w drugiej osobie (you, your), nie w trzeciej'],
  [/not your (lawyers|team|people|staff)|(lawyers|staff|employees|people|associates) (paste|upload|copy)/i, 'problem opisuj przez dokument lub narzędzie, nie przez ludzi (np. „client files end up in public chatbots”)'],
  [/\bjust a tool\b|\bonly a tool\b|\bmerely\b/i, 'nie opisuj Gaius jako „tylko narzędzia”'],
];
for (const [step, fields] of Object.entries(out)) for (const [key, value] of Object.entries(fields)) {
  if (key === 'hide') continue;
  const texts = typeof value === 'string' ? [value] : value.flatMap((it) => Object.values(it));
  const bad = STYLE.filter(([re]) => texts.some((t) => re.test(t))).map(([, why]) => why);
  if (Array.isArray(value)) for (const it of value) if (tileLabels.has(String(it.title || '').toLowerCase())) bad.push(`tytuł „${it.title}” to nazwa kafelka: napisz go słowami klienta`);
  if (bad.length) { problems.push(`"${step}.${key}": ${bad.join('; ')}`); delete fields[key]; }
}
for (const step of Object.keys(out)) if (!Object.keys(out[step]).length) delete out[step];

// Poprawne pola z pierwszej odpowiedzi zostają; poprawka dotyczy tylko pól z błędami.
const earlier = attempt > 1 ? ($('Samopoprawka treści').first().json.keep || {}) : {};
const merged = {};
for (const step of new Set([...Object.keys(earlier), ...Object.keys(out)])) {
  const before = earlier[step] || {};
  const now = out[step] || {};
  merged[step] = { ...before, ...now };
  // Poprawka nie ukrywa slajdu, który pierwsza odpowiedź już napisała (model powtarza wtedy przykład {"hide": true}).
  if (now.hide && Object.keys(now).length === 1 && Object.keys(before).some((k) => k !== 'hide')) delete merged[step].hide;
  // Nowa treść slajdu odkrywa go, chyba że ta sama odpowiedź każe go ukryć.
  if (!now.hide && Object.keys(now).some((k) => k !== 'hide')) delete merged[step].hide;
}

// Porównanie z narzędziem z biblioteki (Copilot, ChatGPT, LEX/Legalis): kolumna narzędzia to wyłącznie jego fakty
// z arkusza sprzedaży, słowo w słowo. Inaczej poprawka; w ostatniej próbie zostają poprawne wiersze (min. 3) albo slajd znika.
{
  const mc = merged['tool-comparison'];
  const known = (ctx.evidence && ctx.evidence.tools) || [];
  const norm = (x) => String(x || '').toLowerCase().replace(/[’‘]/g, "'").replace(/\s+/g, ' ').replace(/[.\s]+$/, '').trim();
  if (mc && !mc.hide && mc.tool) {
    const name = String(mc.tool).toLowerCase();
    const matched = known.filter((t) => [t.name, ...(t.aliases || [])].some((x) => name.includes(String(x).toLowerCase())));
    const facts = matched.flatMap((t) => t.facts || []);
    if (facts.length) {
      const rows = Array.isArray(mc.rows) ? mc.rows : [];
      const ok = rows.filter((r) => facts.some((x) => norm(x.them) === norm(r.value)));
      if (ok.length !== rows.length || rows.length < 3) {
        if (attempt < MAX_TRIES) {
          problems.push(`"tool-comparison.rows": kolumna narzędzia (value) to tylko fakty z biblioteki o ${matched.map((t) => t.name).join(' / ')}, przepisane słowo w słowo, 3–6 wierszy. Dozwolone: ${facts.map((x) => `${x.area}: ‘${x.them}’`).join('; ')}`);
          delete mc.rows;
        } else if (ok.length >= 3) mc.rows = ok;
        else merged['tool-comparison'] = { hide: true };
      }
    }
  }
}

if (problems.length && attempt < MAX_TRIES) {
  // które pola poprawić: "step.field…" z opisu błędu; błąd całej odpowiedzi (np. zły JSON) = poprawka całości
  const fix = {};
  let whole = !Object.keys(out).length;
  for (const p of problems) {
    const m = String(p).match(/^"([^".\[]+)\.([^".\[]+)/);
    if (!m) { whole = true; continue; }
    (fix[m[1]] ||= []).push(m[2]);
  }
  const previous = {};
  for (const [step, keys] of Object.entries(fix)) for (const k of keys) {
    const v = ai && ai.slides && ai.slides[step] && ai.slides[step][k];
    if (v !== undefined) (previous[step] ||= {})[k] = v;
    if (merged[step]) delete merged[step][k];
  }
  return [{ json: { retry: true, attempt, problems, whole, fix, previous, keep: whole ? {} : merged, raw: raw.slice(0, 6000) } }];
}
for (const step of Object.keys(merged)) if (!Object.keys(merged[step]).length) delete merged[step];
if (!Object.keys(merged).length && problems.length) {
  // nic poprawnego: oferta zostaje z tekstami domyślnymi, handlowiec dostaje ostrzeżenie
  return [{ json: { retry: false, attempt, warnings: problems, body: null } }];
}
return [{ json: { retry: false, attempt, warnings: problems, body: { written_by: 'n8n (AI)', slides: merged, lessons: (ctx.lessons || []).map((l) => l.id) } } }];

// Samopoprawka (jedna): gdy błąd dotyczy kilku pól, model poprawia tylko te pola (krótka odpowiedź, reszta zostaje
// z pierwszej odpowiedzi); gdy cała odpowiedź była zła (np. niepoprawny JSON), pisze całość jeszcze raz.
const base = $('Kontekst treści').first().json.prompt;
const j = $json;
const problems = j.problems.map((p) => `- ${p}`).join('
');
const fields = Object.entries(j.fix || {}).map(([s, ks]) => ks.map((k) => `${s}.${k}`).join(', ')).join(', ');
const prompt = j.whole
  ? `${base}

# Poprawka
Twoja poprzednia odpowiedź nie przeszła walidacji:
${problems}

Poprzednia odpowiedź:
"""
${j.raw}
"""

Zwróć cały obiekt JSON jeszcze raz, poprawiony. Skróć teksty ponad limit. W tekstach nie używaj znaku ".`
  : `${base}

# Poprawka tylko tych pól: ${fields}
Reszta Twojej odpowiedzi jest poprawna i zostaje. Te pola nie przeszły walidacji:
${problems}

Twoja poprzednia wersja tych pól:
${JSON.stringify(j.previous)}

Zwróć JSON tylko z tymi polami, w tym samym formacie: {"slides": {"<slajd>": {"<pole>": …}}}. Zachowaj sens, skróć teksty ponad limit (licz znaki). Listę zwróć w całości. W tekstach nie używaj znaku ".`;
return [{ json: { prompt, keep: j.keep || {} } }];

// Nagranie ze strony (base64) -> plik binarny dla ElevenLabs. Przeglądarka nie przepisała mowy (Safari, Firefox, iPhone).
const item = $input.first();
const b = item.json.body || item.json;
const v = b.voice || {};
const mime = String(v.mimeType || 'audio/webm').split(';')[0];
const ext = /mp4|m4a|aac/.test(mime) ? 'm4a' : /ogg/.test(mime) ? 'ogg' : /wav/.test(mime) ? 'wav' : /mpeg|mp3/.test(mime) ? 'mp3' : 'webm';
return [{ json: item.json, binary: { audio: { data: String(v.audioBase64 || ''), mimeType: mime, fileName: `voice.${ext}` } } }];

// Tekst z ElevenLabs trafia tam, gdzie zwykle jest transkrypcja z przeglądarki. Bez klucza albo przy błędzie
// zgłoszenie idzie dalej bez tekstu (oferta z domyślnych kafelków), nigdy nie przerywa workflow.
const original = $('Nagranie → plik').first().json;
const out = JSON.parse(JSON.stringify(original));
const text = String(($json && $json.text) || '').trim();
const b = out.body || out;
b.voice = { ...(b.voice || {}) };
delete b.voice.audioBase64;
if (text) { b.voice.transcript = text; b.voice.transcribedBy = 'ElevenLabs Scribe'; }
else b.voice.transcriptionError = String(($json && $json.error && `ElevenLabs: ${$json.error.message || $json.error}`) || (b.voice.transcriptionError ? `przeglądarka: ${b.voice.transcriptionError}; ElevenLabs: brak tekstu` : 'ElevenLabs: brak tekstu'));
return [{ json: out }];
